def seed_content(apps, schema_editor):
    HomePageContent = apps.get_model("content", "HomePageContent")
    HomeHeroStat = apps.get_model("content", "HomeHeroStat")
    HomeMarqueeItem = apps.get_model("content", "HomeMarqueeItem")
    AboutPageContent = apps.get_model("content", "AboutPageContent")
    ValueProp = apps.get_model("content", "ValueProp")
    TimelineEvent = apps.get_model("content", "TimelineEvent")
    TeamMember = apps.get_model("content", "TeamMember")
    SupportPageContent = apps.get_model("content", "SupportPageContent")
    NotFoundPageContent = apps.get_model("content", "NotFoundPageContent")
    LegalDocument = apps.get_model("content", "LegalDocument")

    # --- Home -------------------------------------------------------------
    home, _ = HomePageContent.objects.get_or_create(pk=1)
    for i, (value, label) in enumerate([
        ("120 km", "Max Range"),
        ("35 kW", "Peak Power"),
        ("112 kg", "Curb Weight"),
        ("30 sec", "Battery Swap"),
    ]):
        HomeHeroStat.objects.get_or_create(home=home, value=value, label=label, defaults={"sort_order": i})
    for i, text in enumerate(["FREE EU DELIVERY", "3-YEAR BATTERY WARRANTY", "0% APR FINANCING"]):
        HomeMarqueeItem.objects.get_or_create(home=home, text=text, defaults={"sort_order": i})

    # --- About --------------------------------------------------------------
    about, _ = AboutPageContent.objects.get_or_create(pk=1)
    for i, (icon, title, body) in enumerate([
        ("bx-bolt", "Electric First", "We don\'t make gas bikes and add a battery. Every {trade_name} is designed from the ground up as an electric machine — frame, motor, and battery as one system."),
        ("bx-shield-alt", "Built to Last", "Aircraft-grade aluminium, sealed bearings, and IP67-rated electronics. Our bikes are overbuilt because we\'d rather you ride than visit a workshop."),
        ("bx-leaf", "Zero Compromise", "Zero emissions doesn\'t mean zero performance. We prove that electric can outperform combustion on the trail, on the road, and on the track."),
    ]):
        ValueProp.objects.get_or_create(about=about, title=title, defaults={"icon": icon, "body": body, "sort_order": i})

    for i, (year, title, body) in enumerate([
        ("2021", "The Idea", "Co-founders Karim Belkacem and Lila Ait Ahmed sketch the first Pihilics concept in a Setif workshop. The goal: an electric enduro that actually works on Algerian terrain."),
        ("2022", "First Prototype", "The Pihilics-0 prototype completes its first test in the Babor mountains. 25 kW, 80 km range, and a frame welded in a rented workshop in Setif."),
        ("2023", "Series A & Setif Factory", "1.6 billion DA Series A funding. We move into our Setif industrial-zone production facility and begin small-batch production of the RVX."),
        ("2024", "RVX Launch & First Dealers", "The Pihilics RVX ships to early customers. We open our first three dealers in Setif, Alger, and Oran."),
        ("2025", "Full Fleet & EU Expansion", "The Trail, Adventure, and Performance lines launch. We expand to 8 dealers across 8 wilayas, north to south."),
        ("2026", "Performance RS & Beyond", "The limited-edition Performance RS sells out in 48 hours. We announce plans for North American expansion in 2027."),
    ]):
        TimelineEvent.objects.get_or_create(about=about, year=year, title=title, defaults={"body": body, "sort_order": i})

    for i, (name, role) in enumerate([
        ("Erik Volker", "Co-Founder & CEO"),
        ("Mia Brandt", "Co-Founder & CTO"),
        ("Klaus Reiner", "Head of Design"),
        ("Sara Okonkwo", "Head of Operations"),
    ]):
        TeamMember.objects.get_or_create(about=about, name=name, defaults={"role": role, "sort_order": i})

    # --- Support / 404 --------------------------------------------------
    SupportPageContent.objects.get_or_create(pk=1)
    NotFoundPageContent.objects.get_or_create(pk=1)

    # --- Legal ------------------------------------------------------------
    LegalDocument.objects.get_or_create(
        slug="terms",
        defaults={"title": "Terms of Service", "last_updated": "2026-09-01", "body": TERMS_BODY},
    )
    LegalDocument.objects.get_or_create(
        slug="privacy",
        defaults={"title": "Privacy Policy", "last_updated": "2026-09-01", "body": PRIVACY_BODY},
    )


def unseed_content(apps, schema_editor):
    # Reverse migration: leave the singleton rows (an empty admin form is
    # a worse experience than stale seed copy) but drop the two legal
    # documents, since re-running forward would otherwise collide with
    # their unique slug.
    LegalDocument = apps.get_model("content", "LegalDocument")
    LegalDocument.objects.filter(slug__in=["terms", "privacy"]).delete()


